def pick(table, sector, country, region, rng, avoid=(), city="", icao=""):
    """A company from the table that fits the sector and the place: the airport first, then the country, the region,
    then anyone. Within a level it prefers one not used yet on this flight, but repeats a local company rather than
    reaching for a faraway one."""
    rows = table.get(sector) or table["general"]
    for want in (icao, country, "@" + region if region else None, "*"):
        if not want:
            continue
        hit = [n for n, where in rows if want in where]
        if hit:
            fresh = [n for n in hit if n not in avoid]
            return rng.choice(fresh or hit).replace("{city}", city)
    rows = table["general"]
    hit = [n for n, where in rows if country in where or "*" in where]
    return (rng.choice(hit) if hit else "Consignee on file").replace("{city}", city)


REGIONAL_FORWARDERS = {"AGL (Africa Global Logistics)": "AF"}     # only where they operate


def forwarder(sector, rng, regions=()):
    rows = [f for f in (FORWARDERS.get(sector) or FORWARDERS["general"]) if f not in REGIONAL_FORWARDERS or REGIONAL_FORWARDERS[f] in regions]
    return rng.choice(rows or FORWARDERS["general"])


def handler(icao, airport_name):
    name = (airport_name or icao).split(" (")[0]
    return HANDLERS.get(icao) or f"{name} cargo terminal"


GLOBAL_EXPRESS = {"DHL Express", "FedEx", "UPS", "Amazon", "DPD", "GLS", "TNT (FedEx)", "Aramex", "SF Express"}


def express_consignee(shipper, city, international):
    """Express networks fly their own freight, so the same company receives it; a national carrier's international
    express goes to a global network's gateway for delivery."""
    base = shipper.split(" (")[0]
    if shipper in GLOBAL_EXPRESS or base in GLOBAL_EXPRESS or not international:
        return f"{base} {city} hub"
    return f"DHL Express {city} gateway"
